import path = require('path');
import {ipcMain, app, BrowserWindow} from 'electron';
import findRoot = require('find-root');
import {EventEmitter} from 'events';
import Log = require('jibo-log');

import SystemManagerClient from '../clients/SystemManagerClient';
import {SkillRecord} from '../clients/SystemManagerClient';

let log = new Log('ssm-main-process');
log.toSyslog(); // only works on linux/arm



//console.log('before quit');
class MainProcess extends EventEmitter {

    private static WIDTH:number = 1280;
    private static HEIGHT:number = 720;

    private skillWindow:BrowserWindow;

    constructor() {
        super();
        SystemManagerClient.createInstance('127.0.0.1', 8585);

        log.debug('SSM Started');

        this.onReady = this.onReady.bind(this);
        this.onCrashed = this.onCrashed.bind(this);
        this.onShow = this.onShow.bind(this);
        this.onHide = this.onHide.bind(this);
        this.onGetPid = this.onGetPid.bind(this);

        // process.on('SIGINT', function(event) {
        //     console.log("Caught interrupt signal");
        //     setTimeout(() => {
        //         console.log('REALLY EXIT');
        //         process.exit();
        //     }, 5000);
        //     // this.skillWindow.webContents.send('cleanup');
        // });

        if(!app.isReady()) {
            app.on('ready', this.onReady);
        }
        else {
            this.onReady();
        }

        ipcMain.on('show', this.onShow);
        ipcMain.on('hide', this.onHide);
        ipcMain.on('get-pid', this.onGetPid);
        ipcMain.on('cleanedup', () => {
            app.quit();
        });
    }

    private onShow() {
        //console.log('onShow');
        this.skillWindow.show();
        this.skillWindow.focus();
        this.skillWindow.setPosition(0, 0);
    }

    private onHide() {
        this.skillWindow.hide();
    }

    private onCrashed() {
        log.error('SSM Renderer Process Crashed');
        // this.skillWindow.webContents.removeAllListeners();
        // this.skillWindow.removeAllListeners();
        // this.skillWindow.close();
        log.error('Checking for running skills');
        SystemManagerClient.instance.list((error:Error, records:Array<SkillRecord>) => {
            if(error) {
                log.error('System Manager error. Restarting SSM.', error);
                return this.onReady();
            }
            for(let i = 0; i < records.length; i++) {
                if(records[i].running) {
                    log.error('Terminating ', records[i].name);
                    SystemManagerClient.instance.terminate(records[i].name, (error:Error) => {
                        log.error('Restarting SSM renderer process');
                        this.skillWindow.reload();
                    });
                    return;
                }
            }
            log.error('No skill to shut down. Restarting SSM renderer process');
            this.onReady();
        });
    }

    /**
     * Called when the main process is ready
     */
    private onReady():void {

        this.skillWindow = new BrowserWindow({
            x: 0,
            y: 0,
            show: false,
            width: MainProcess.WIDTH,
            height: MainProcess.HEIGHT,
            backgroundColor: '#000000',
            frame: false
        });

        this.skillWindow.on('closed', this.onSkillWindowClosed);
        this.skillWindow.webContents.on('crashed', this.onCrashed);

        // this.skillWindow.on('close', (event) => {
        //     console.log('SKILL WINDOW CLOSE');
        //     event.preventDefault();
        // });
        let indexPath:string = path.join(findRoot(__dirname), 'index.html');

        console.log('onReady', indexPath);

        //load the skill
        this.skillWindow.loadURL('file://' + indexPath);
        this.skillWindow.webContents.once('did-finish-load', () => {
            this.skillWindow.show();
        });

        // this.skillWindow.openDevTools({detach: true});
        //setTimeout(()=> {
        //    this.skillWindow.reload();
        //}, 5000);
        // this.skillWindow.hide();
    }

    /**
     * Called if the skill window closes.
     */
    private onSkillWindowClosed():void {
        // console.log('SKILL WINDOW CLOSED');
        this.skillWindow = null;
    }

    /**
     * Called when the `jibo` module requests initialization data
     * @param event
     */
    private onGetPid(event):void {
        event.sender.send('set-pid', process.pid);
    }
}

export default function() {
    return new MainProcess();
}
